import{_ as r,l,o as e,c as n,v as t,p as s,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"故障注入","description":"","frontmatter":{"title":"故障注入","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fault-injection.md","filePath":"cs/fault-injection.md","lastUpdated":1789023840000}'),c={name:"cs/fault-injection.md"};function E(_,a,u,A,f,m){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="故障注入" tabindex="-1">故障注入 <a class="header-anchor" href="#故障注入" aria-label="Permalink to &quot;故障注入&quot;">​</a></h1><div class="epigraph"><p>电压、时钟或激光让芯片算错一轮，错误输出可能泄漏密钥或跳过校验。防护是冗余、检测与失败即关，而不是假设封装等于物理不可及。</p><footer>—— Boneh, DeMillo and Lipton, On the Importance of Checking Cryptographic Protocols for Faults, EUROCRYPT 1997</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/power-analysis-dpa">DPA</a>是被动观测。缺口是<strong>主动让计算出错</strong>。本课讲故障与检测，不给注入实验步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RSA CRT 一类实现在错误输出下可泄漏因子——只陈述「要验证计算结果」。缺口是冗余与传感器。</p><h3 id="安全元件" tabindex="-1">安全元件 <a class="header-anchor" href="#安全元件" aria-label="Permalink to &quot;安全元件&quot;">​</a></h3><p>认证实验室测故障。软件栈不能假设芯片无故障。</p><p><span class="marginnote">Boneh–DeMillo–Lipton。禁止故障注入实验指导。PUF 下一课把物理不可克隆当身份。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照被动/主动物理。对策：重复计算、校验、故障传感器。下一课 PUF。</p>',12)),(e(),s(h,null,{default:o(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAULT%5B%22%E7%8E%AF%E5%A2%83%E6%89%B0%E5%8A%A8%22%5D%20--%3E%20ERR%5B%22%E9%94%99%E8%AF%AF%E4%B8%AD%E9%97%B4%E5%80%BC%22%5D%0A%20%20ERR%20--%3E%20LEAK%5B%22%E6%88%96%E8%B7%B3%E8%BF%87%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20CHK%5B%22%E5%86%97%E4%BD%99%E6%A3%80%E6%B5%8B%22%5D%20--%3E%20FAIL%5B%22%E6%8B%92%E7%BB%9D%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>完整在物理层：计算必须自检。PUF 用物理差异当指纹，模型不同。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零实验配方。PUF 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DPA 被动；故障主动改计算。</li><li>错误输出可伤密钥；要校验。</li><li>封装不是物理不可及证明。</li><li>下一课 PUF。</li><li>出处：Boneh, DeMillo and Lipton, 1997。</li></ul>',8))])}const T=r(c,[["render",E]]);export{P as __pageData,T as default};
